-- Run once in the Supabase SQL editor.
create table if not exists public.store_settings(id text primary key default 'main',settings jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists public.products(id text primary key,data jsonb not null,active boolean not null default true,sort_order integer not null default 999,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.orders(id text primary key,data jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.custom_requests(id text primary key,data jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.reviews(id text primary key,data jsonb not null,status text not null default 'À modérer',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.contact_messages(id text primary key,data jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.newsletter_subscribers(id text primary key,data jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists newsletter_subscribers_email_idx on public.newsletter_subscribers((lower(data->>'email')));
insert into public.store_settings(id,settings) values('main','{}'::jsonb) on conflict(id) do nothing;
alter table public.store_settings enable row level security; alter table public.products enable row level security; alter table public.orders enable row level security; alter table public.custom_requests enable row level security; alter table public.reviews enable row level security; alter table public.contact_messages enable row level security; alter table public.newsletter_subscribers enable row level security;
create policy "public_read_settings" on public.store_settings for select to anon,authenticated using(true); create policy "staff_settings" on public.store_settings for all to authenticated using(true) with check(true);
create policy "public_read_products" on public.products for select to anon using(active=true); create policy "staff_products" on public.products for all to authenticated using(true) with check(true);
create policy "public_create_orders" on public.orders for insert to anon with check(true); create policy "staff_orders" on public.orders for all to authenticated using(true) with check(true);
create policy "public_create_custom" on public.custom_requests for insert to anon with check(true); create policy "staff_custom" on public.custom_requests for all to authenticated using(true) with check(true);
create policy "public_create_reviews" on public.reviews for insert to anon with check(status='À modérer'); create policy "public_read_reviews" on public.reviews for select to anon using(status='Publié'); create policy "staff_reviews" on public.reviews for all to authenticated using(true) with check(true);
create policy "public_create_messages" on public.contact_messages for insert to anon with check(true); create policy "staff_messages" on public.contact_messages for all to authenticated using(true) with check(true);
create policy "public_create_newsletter" on public.newsletter_subscribers for insert to anon with check(true); create policy "staff_newsletter" on public.newsletter_subscribers for all to authenticated using(true) with check(true);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',true,12582912,array['image/jpeg','image/png','image/webp','image/avif']) on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "public_product_images" on storage.objects for select to anon,authenticated using(bucket_id='product-images'); create policy "staff_upload_product_images" on storage.objects for insert to authenticated with check(bucket_id='product-images'); create policy "staff_update_product_images" on storage.objects for update to authenticated using(bucket_id='product-images') with check(bucket_id='product-images'); create policy "staff_delete_product_images" on storage.objects for delete to authenticated using(bucket_id='product-images');
